changeSet.sql:
CREATE TABLE plugin_policies_job (
    id SERIAL PRIMARY KEY,
    customerId INT NOT NULL,
    createdBy INT,
    action VARCHAR(32) NOT NULL,
    label VARCHAR(200),
    createdAt BIGINT NOT NULL,
    cancelled BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE INDEX plugin_policies_job_customer_idx ON plugin_policies_job (customerId, createdAt);

CREATE TABLE plugin_policies_job_device (
    id SERIAL PRIMARY KEY,
    jobId INT NOT NULL REFERENCES plugin_policies_job (id) ON DELETE CASCADE,
    deviceNumber VARCHAR(100) NOT NULL,
    wake VARCHAR(16) NOT NULL DEFAULT 'queued',
    wokenAt BIGINT
);
CREATE INDEX plugin_policies_job_device_job_idx ON plugin_policies_job_device (jobId);
CREATE INDEX plugin_policies_job_device_queued_idx ON plugin_policies_job_device (id) WHERE wake = 'queued';

CREATE TABLE plugin_policies_job_command (
    id SERIAL PRIMARY KEY,
    jobId INT NOT NULL REFERENCES plugin_policies_job (id) ON DELETE CASCADE,
    deviceNumber VARCHAR(100) NOT NULL,
    commandId INT NOT NULL,
    attempts INT NOT NULL DEFAULT 1
);
CREATE INDEX plugin_policies_job_command_job_idx ON plugin_policies_job_command (jobId);
CREATE INDEX plugin_policies_job_command_cmd_idx ON plugin_policies_job_command (commandId);

changeSet.rollback:
DROP TABLE plugin_policies_job_command;
DROP TABLE plugin_policies_job_device;
DROP TABLE plugin_policies_job;

changeSet.sql:
CREATE TABLE plugin_policies_group (
    id SERIAL PRIMARY KEY,
    customerId INT NOT NULL,
    name VARCHAR(100) NOT NULL,
    configurationId INT,
    createdAt BIGINT NOT NULL
);
CREATE INDEX plugin_policies_group_customer_idx ON plugin_policies_group (customerId);

CREATE TABLE plugin_policies_group_brand (
    customerId INT NOT NULL,
    brand VARCHAR(40) NOT NULL,
    groupId INT NOT NULL REFERENCES plugin_policies_group (id) ON DELETE CASCADE,
    PRIMARY KEY (customerId, brand)
);
CREATE INDEX plugin_policies_group_brand_group_idx ON plugin_policies_group_brand (groupId);

CREATE TABLE plugin_policies_group_device (
    deviceId INT PRIMARY KEY,
    customerId INT NOT NULL,
    groupId INT NOT NULL REFERENCES plugin_policies_group (id) ON DELETE CASCADE
);
CREATE INDEX plugin_policies_group_device_group_idx ON plugin_policies_group_device (groupId);

CREATE TABLE plugin_policies_brand (
    customerId INT NOT NULL,
    brand VARCHAR(40) NOT NULL,
    label VARCHAR(40) NOT NULL,
    PRIMARY KEY (customerId, brand)
);

CREATE TABLE plugin_policies_device_brand (
    deviceId INT PRIMARY KEY,
    customerId INT NOT NULL,
    brand VARCHAR(40) NOT NULL
);

changeSet.rollback:
DROP TABLE plugin_policies_device_brand;
DROP TABLE plugin_policies_brand;
DROP TABLE plugin_policies_group_device;
DROP TABLE plugin_policies_group_brand;
DROP TABLE plugin_policies_group;
